package main

import (
	"crypto/aes"
	"crypto/cipher"
	"crypto/rand"
	"encoding/hex"
	"fmt"
	"io"
	"log"
	"net/smtp"
	"sync"
	"time"
)

type EmailService struct {
	mu        sync.Mutex
	smtpHost  string
	smtpPort  string
	encKey    []byte
	noncePool *NoncePool
}

type NoncePool struct {
	mu      sync.Mutex
	nonces  [][]byte
	capacity int
	refillCh chan struct{}
}

func NewNoncePool(capacity int) *NoncePool {
	np := &NoncePool{
		nonces:   make([][]byte, 0, capacity),
		capacity: capacity,
		refillCh: make(chan struct{}, 1),
	}
	np.refill()
	go np.backgroundRefill()
	return np
}

func (np *NoncePool) refill() {
	np.mu.Lock()
	defer np.mu.Unlock()
	for len(np.nonces) < np.capacity {
		nonce := make([]byte, 12)
		if _, err := io.ReadFull(rand.Reader, nonce); err != nil {
			log.Printf("nonce generation error: %v", err)
			return
		}
		np.nonces = append(np.nonces, nonce)
	}
}

func (np *NoncePool) backgroundRefill() {
	for range np.refillCh {
		time.Sleep(10 * time.Millisecond)
		np.refill()
	}
}

func (np *NoncePool) Acquire() []byte {
	np.mu.Lock()
	if len(np.nonces) == 0 {
		np.mu.Unlock()
		select {
		case np.refillCh <- struct{}{}:
		default:
		}
		time.Sleep(15 * time.Millisecond)
		np.mu.Lock()
		if len(np.nonces) == 0 {
			np.mu.Unlock()
			nonce := make([]byte, 12)
			io.ReadFull(rand.Reader, nonce)
			return nonce
		}
	}
	nonce := np.nonces[len(np.nonces)-1]
	np.nonces = np.nonces[:len(np.nonces)-1]
	np.mu.Unlock()
	if len(np.nonces) < np.capacity/4 {
		select {
		case np.refillCh <- struct{}{}:
		default:
		}
	}
	return nonce
}

func (np *NoncePool) Release(nonce []byte) {
	np.mu.Lock()
	defer np.mu.Unlock()
	if len(np.nonces) < np.capacity {
		np.nonces = append(np.nonces, nonce)
	}
}

func NewEmailService(host, port string, key []byte) *EmailService {
	return &EmailService{
		smtpHost:  host,
		smtpPort:  port,
		encKey:    key,
		noncePool: NewNoncePool(64),
	}
}

func (es *EmailService) encryptBody(plaintext []byte) (string, error) {
	block, err := aes.NewCipher(es.encKey)
	if err != nil {
		return "", fmt.Errorf("cipher creation failed: %w", err)
	}

	aesgcm, err := cipher.NewGCM(block)
	if err != nil {
		return "", fmt.Errorf("GCM creation failed: %w", err)
	}

	nonce := es.noncePool.Acquire()

	ciphertext := aesgcm.Seal(nonce, nonce, plaintext, nil)
	return hex.EncodeToString(ciphertext), nil
}

type EmailRequest struct {
	To      string
	From    string
	Subject string
	Body    string
}

func (es *EmailService) SendAsync(req EmailRequest, resultCh chan<- error) {
	go func() {
		encBody, err := es.encryptBody([]byte(req.Body))
		if err != nil {
			resultCh <- err
			return
		}

		msg := fmt.Sprintf("From: %s\r\nTo: %s\r\nSubject: %s\r\n\r\n%s",
			req.From, req.To, req.Subject, encBody)

		err = smtp.SendMail(
			es.smtpHost+":"+es.smtpPort,
			nil,
			req.From,
			[]string{req.To},
			[]byte(msg),
		)
		resultCh <- err
	}()
}

func (es *EmailService) SendBatch(requests []EmailRequest) []error {
	resultCh := make(chan error, len(requests))

	for _, req := range requests {
		es.SendAsync(req, resultCh)
	}

	errors := make([]error, 0, len(requests))
	for i := 0; i < len(requests); i++ {
		errors = append(errors, <-resultCh)
	}
	return errors
}

func main() {
	key := make([]byte, 32)
	if _, err := io.ReadFull(rand.Reader, key); err != nil {
		log.Fatal(err)
	}

	service := NewEmailService("smtp.example.com", "587", key)

	requests := []EmailRequest{
		{To: "alice@example.com", From: "system@example.com", Subject: "Report", Body: "Q1 financials attached"},
		{To: "bob@example.com", From: "system@example.com", Subject: "Report", Body: "Q2 financials attached"},
		{To: "carol@example.com", From: "system@example.com", Subject: "Report", Body: "Q3 financials attached"},
	}

	errs := service.SendBatch(requests)
	for i, err := range errs {
		if err != nil {
			log.Printf("Email %d failed: %v", i, err)
		}
	}
}
